def calcular_frete(peso_kg: float, regiao: str, valor_pedido: float, cupom: str | None = None, expresso: bool = False) -> float:
    # 1. Validação
    if not (0 < peso_kg <= 30):
        raise ValueError("Peso inválido")
    if regiao not in ("S", "SE", "CO", "NE", "N"):
        raise ValueError("Região inválida")
    if valor_pedido < 0:
        raise ValueError("Valor do pedido inválido")

    # Converter para Decimal para cálculos financeiros precisos
    peso_dec = Decimal(str(peso_kg))
    valor_dec = Decimal(str(valor_pedido))

    # 2. Tarifa base por peso
    if peso_dec <= Decimal('1'):
        tarifa_base = Decimal('12.00')
    elif peso_dec <= Decimal('5'):
        # R$ 12,00 + R$ 3,50 por kg adicional OU FRAÇÃO acima de 1 kg
        extra_kg = math.ceil(float(peso_dec - Decimal('1')))
        tarifa_base = Decimal('12.00') + Decimal('3.50') * extra_kg
    else:
        # R$ 26,00 + R$ 2,80 por kg OU FRAÇÃO acima de 5 kg
        extra_kg = math.ceil(float(peso_dec - Decimal('5')))
        tarifa_base = Decimal('26.00') + Decimal('2.80') * extra_kg

    # 3. Multiplicador regional sobre a tarifa base
    multiplicadores = {
        "S": Decimal('1.00'),
        "SE": Decimal('1.00'),
        "CO": Decimal('1.20'),
        "NE": Decimal('1.35'),
        "N": Decimal('1.50')
    }
    tarifa_regional = tarifa_base * multiplicadores[regiao]

    # 4. Expresso: +40% sobre o valor obtido no passo 3
    if expresso:
        tarifa_regional = tarifa_regional * Decimal('1.40')

    # 5. Frete grátis: se valor_pedido >= 299,90 E não for expresso E a região for S, SE ou CO
    if valor_dec >= Decimal('299.90') and not expresso and regiao in ("S", "SE", "CO"):
        return 0.0

    # 6. Cupons
    desconto_cupom = Decimal('0.00')
    if cupom is None or cupom == "":
        pass
    else:
        cupom_upper = cupom.upper()
        if cupom_upper == "FRETE10":
            desconto_cupom = Decimal('0.10')
        elif cupom_upper == "FRETEMETADE":
            if peso_kg <= 5:
                desconto_cupom = Decimal('0.50')
            else:
                # senão o cupom é ignorado
                desconto_cupom = Decimal('0.00')
        else:
            raise ValueError("Cupom inválido")

    # Aplicar desconto
    if desconto_cupom > 0:
        tarifa_final = tarifa_regional * (Decimal('1') - desconto_cupom)
    else:
        tarifa_final = tarifa_regional

    # 7. Frete mínimo: depois dos descontos, o frete nunca é menor que R$ 9,90
    if tarifa_final < Decimal('9.90'):
        tarifa_final = Decimal('9.90')

    # 8. Arredonde o resultado final para 2 casas decimais com arredondamento comercial (meio para cima, ROUND_HALF_UP)
    tarifa_final_rounded = tarifa_final.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return float(tarifa_final_rounded)

